def closures(evts, window, delta=DELTA):
    # adjacency: node -> list of (t, other) sorted
    adj=collections.defaultdict(list)
    for u,v,t in evts:
        adj[u].append((t,v)); adj[v].append((t,u))
    for k in adj: adj[k].sort()
    res=[]
    for u,v,t in evts:
        if not (window[0]<=t<=window[1]): continue
        # find common neighbors c with u-c at t1<=t and v-c at t2<=t, max(t1,t2)>=t-delta
        # collect u's contacts before t
        cu={}
        for tt,w in adj[u]:
            if tt> t: break
            if w!=v: cu[w]=tt   # last time
        cv={}
        for tt,w in adj[v]:
            if tt> t: break
            if w!=u: cv[w]=tt
        for c in cu:
            if c in cv:
                # earliest establishment of the wedge: min over combos? use first times
                pass
        # use first-time versions
        fu={}; fv={}
        for tt,w in adj[u]:
            if tt>t: break
            if w!=v and w not in fu: fu[w]=tt
        for tt,w in adj[v]:
            if tt>t: break
            if w!=u and w not in fv: fv[w]=tt
        for c in set(fu)&set(fv):
            wedge=max(fu[c],fv[c])
            lag=t-wedge
            if 0<=lag<=delta:
                res.append((u,v,t,c,wedge,lag))
    return res

